<?php
namespace Database\Seeders;use App\Models\{Property,TaxRule,PaymentGatewayConfig,NotificationProviderConfig,OnboardingState};use Illuminate\Database\Seeder;
class HotelGoLiveSeeder extends Seeder{public function run():void{foreach(Property::where('is_active',true)->get() as $p){TaxRule::firstOrCreate(['property_id'=>$p->id,'code'=>'VAT'],['name'=>'VAT','rate'=>0,'type'=>'percentage','inclusive'=>false,'is_active'=>false]);foreach(['mtn_momo'=>'MTN MoMo','airtel_money'=>'Airtel Money','pesapal'=>'Pesapal','flutterwave'=>'Flutterwave'] as $g=>$label)PaymentGatewayConfig::firstOrCreate(['property_id'=>$p->id,'gateway'=>$g],['label'=>$label,'enabled'=>false,'sandbox'=>true]);foreach(['email'=>'smtp','sms'=>'unconfigured','whatsapp'=>'unconfigured','push'=>'firebase'] as $ch=>$provider)NotificationProviderConfig::firstOrCreate(['property_id'=>$p->id,'channel'=>$ch],['provider'=>$provider,'enabled'=>false]);foreach(['property','users','rooms','tax','payments','printers','notifications','backup','go_live'] as $step)OnboardingState::firstOrCreate(['property_id'=>$p->id,'step'=>$step],['completed'=>false]);}}}
